{"cards": [{"node_code": "N_eb1ca4f4a225b8e4", "definition": "描述材料在弹性范围内应力与应变线性或广义线性关系的本构模型，涵盖胡克定律、弹性常数及各向异性弹性理论。", "boundary": "聚焦于可恢复变形阶段的力学响应，即卸载后无残余变形的状态。包括各向同性、正交各向异性及完全各向异性材料的弹性张量描述。不涉及塑性屈服、永久变形或时间依赖的松弛/蠕变行为。", "includes": ["广义胡克定律及弹性刚度/柔度张量", "弹性常数（如杨氏模量、泊松比、剪切模量）的物理意义与测定", "各向异性材料（如复合材料、晶体）的弹性本构关系"], "excludes": ["涉及塑性流动或屈服面的本构模型", "包含时间项的黏弹性或黏塑性模型"], "sibling_distinctions": [{"other_code": "N_d614bb9811b3bfc7", "rule": "本节点处理可逆的弹性变形，兄弟节点处理不可逆的塑性变形；若应力低于屈服极限归本节点，超过则归兄弟节点。"}, {"other_code": "N_1dd913cbd7443b40", "rule": "本节点假设响应与时间无关（瞬时弹性），兄弟节点处理响应随时间变化（如蠕变、松弛）；纯弹性无时间项归本节点。"}], "cross_boundary_rule": ""}, {"node_code": "N_d614bb9811b3bfc7", "definition": "描述材料进入塑性状态后的屈服条件、流动方向及硬化规律的本构理论，涵盖屈服准则、塑性势函数及强化模型。", "boundary": "聚焦于不可逆塑性变形的力学描述，包括屈服面（如Mises、Tresca、Hill）、法向流动法则及各向同性/各向异性硬化。不涉及弹性阶段的线性关系或时间依赖的黏性效应。", "includes": ["屈服准则的数学表达与物理意义", "塑性流动法则（关联/非关联）及塑性势函数", "塑性强化理论（如线性硬化、Ramberg-Osgood模型）"], "excludes": ["纯弹性范围内的应力应变分析", "包含显著时间依赖性的黏塑性模型"], "sibling_distinctions": [{"other_code": "N_eb1ca4f4a225b8e4", "rule": "本节点处理超过屈服极限后的不可逆变形，兄弟节点处理弹性可逆变形；涉及屈服判断或塑性应变增量归本节点。"}, {"other_code": "N_1dd913cbd7443b40", "rule": "本节点通常假设塑性流动与时间无关（理想塑性或率无关），兄弟节点显式包含时间或应变率依赖；若强调应变率敏感性归兄弟节点。"}], "cross_boundary_rule": ""}, {"node_code": "N_1dd913cbd7443b40", "definition": "描述材料力学响应随时间或应变率变化的本构模型，涵盖黏弹性（蠕变、松弛）及黏塑性（率相关塑性）行为。", "boundary": "聚焦于时间依赖或率相关的力学行为，包括线性/非线性黏弹性模型（如Maxwell、Kelvin-Voigt）及考虑应变率效应的塑性模型。不涉及纯弹性或纯理想塑性（率无关）的静态本构关系。", "includes": ["线性与非线性黏弹性本构方程及微分/积分形式", "蠕变、应力松弛及滞后现象的力学描述", "率相关塑性模型及高温下的黏塑性本构关系"], "excludes": ["与时间无关的纯弹性或理想塑性本构模型", "纯热传导或纯化学扩散过程（除非耦合于力学响应）"], "sibling_distinctions": [{"other_code": "N_eb1ca4f4a225b8e4", "rule": "本节点包含时间项或应变率项，兄弟节点为瞬时响应；若涉及蠕变或松弛归本节点，若为瞬时弹性归兄弟节点。"}, {"other_code": "N_d614bb9811b3bfc7", "rule": "本节点强调应变率对屈服/流动的影响，兄弟节点通常假设率无关；若需考虑加载速度对强度的影响归本节点。"}], "cross_boundary_rule": ""}]}
